package com.storageplanner.core;

/**
 * Eye open / closed from an eye patch. Small neural network (304 features, 16 hidden units) trained on
 * real faces: Closed Eyes In The Wild (closed) and an aligned open-eye face set, with augmentation for
 * resolution, roll, JPEG, noise and eye-position error (to match what Android's face detector reports).
 * Held-out faces: AUC 0.987, 95% accuracy (see README). Features are ported 1:1 from the training script.
 */
public final class EyeState {
    private EyeState() {}

    static final int PW = 24, PH = 16, CELL = 4, BINS = 8, NF = 304, NH = 16;
    static final double SPAN_W = 0.75, SPAN_H = 0.5;

    private static final float[] W = load();

    private static float[] load() {
        byte[] raw = java.util.Base64.getDecoder().decode(MODEL);
        java.nio.FloatBuffer fb = java.nio.ByteBuffer.wrap(raw).order(java.nio.ByteOrder.LITTLE_ENDIAN).asFloatBuffer();
        float[] w = new float[fb.remaining()];
        fb.get(w);
        if (w.length != NH * NF + NH + NH + 1) throw new IllegalStateException("eye model size " + w.length);
        return w;
    }

    /**
     * Probability that the eyes of one face are open (mean of both eyes).
     * mx, my: point between the eyes; d: distance between the eyes (luma image pixels).
     */
    public static double openProbability(int[] luma, int w, int h, double mx, double my, double d) {
        // averaged over small shifts of the eye position: a phone's detector places eyes less precisely
        double sum = 0; int n = 0;
        for (double[] o : SHIFTS) {
            double x = mx + o[0] * d, y = my + o[1] * d, dd = d * o[2];
            sum += eye(luma, w, h, x - dd / 2, y, dd, false) + eye(luma, w, h, x + dd / 2, y, dd, true);
            n += 2;
        }
        return sum / n;
    }

    /** {dx, dy (eye distances), scale} */
    static final double[][] SHIFTS = {{0, 0, 1}, {0, -0.06, 1}, {0, 0.06, 1}, {-0.06, 0, 1}, {0.06, 0, 1}, {0, 0, 0.92}, {0, 0, 1.08}};

    /** Probability for one eye (mirror = true for the image-right eye, so both look alike to the model). */
    public static double eye(int[] luma, int w, int h, double cx, double cy, double d, boolean mirror) {
        return predict(features(patch(luma, w, h, cx, cy, d, mirror)));
    }

    static double sample(int[] l, int w, int h, double x, double y) {
        x = Math.min(Math.max(x, 0.0), w - 1.0); y = Math.min(Math.max(y, 0.0), h - 1.0);
        int x0 = (int) Math.floor(x), y0 = (int) Math.floor(y);
        int x1 = Math.min(x0 + 1, w - 1), y1 = Math.min(y0 + 1, h - 1);
        double fx = x - x0, fy = y - y0;
        return (l[y0 * w + x0] * (1 - fx) + l[y0 * w + x1] * fx) * (1 - fy) + (l[y1 * w + x0] * (1 - fx) + l[y1 * w + x1] * fx) * fy;
    }

    /** PWxPH patch centred on an eye; each pixel is the mean of 3x3 bilinear sub-samples. */
    static double[] patch(int[] l, int w, int h, double cx, double cy, double d, boolean mirror) {
        double[] p = new double[PW * PH];
        double sw = SPAN_W * d / PW, sh = SPAN_H * d / PH;
        for (int j = 0; j < PH; j++)
            for (int i = 0; i < PW; i++) {
                int ii = mirror ? PW - 1 - i : i;
                double acc = 0;
                for (int sy = 0; sy < 3; sy++)
                    for (int sx = 0; sx < 3; sx++) {
                        double x = cx + ((ii + (sx + 0.5) / 3.0) - PW / 2.0) * sw;
                        double y = cy + ((j + (sy + 0.5) / 3.0) - PH / 2.0) * sh;
                        acc += sample(l, w, h, x, y);
                    }
                p[j * PW + i] = acc / 9.0;
            }
        return p;
    }

    static double[] features(double[] p) {
        int n = p.length;
        double m = 0; for (double v : p) m += v; m /= n;
        double var = 0; for (double v : p) var += (v - m) * (v - m);
        double s = Math.sqrt(var / n);
        double[] nn = new double[n];
        for (int i = 0; i < n; i++) nn[i] = (p[i] - m) / (s + 4.0);
        double[] f = new double[NF];
        int k = 0;
        for (int cy = 0; cy < PH / CELL; cy++)
            for (int cx = 0; cx < PW / CELL; cx++) {
                for (int y = cy * CELL; y < cy * CELL + CELL; y++)
                    for (int x = cx * CELL; x < cx * CELL + CELL; x++) {
                        double gx = nn[y * PW + Math.min(x + 1, PW - 1)] - nn[y * PW + Math.max(x - 1, 0)];
                        double gy = nn[Math.min(y + 1, PH - 1) * PW + x] - nn[Math.max(y - 1, 0) * PW + x];
                        double mag = Math.sqrt(gx * gx + gy * gy);
                        double ang = Math.atan2(gy, gx);
                        if (ang < 0) ang += Math.PI;
                        if (ang >= Math.PI) ang -= Math.PI;
                        double pos = ang / Math.PI * BINS - 0.5;
                        int b0 = (int) Math.floor(pos); double fr = pos - b0;
                        f[k + Math.floorMod(b0, BINS)] += mag * (1 - fr);
                        f[k + Math.floorMod(b0 + 1, BINS)] += mag * fr;
                    }
                k += BINS;
            }
        double ss = 0; for (int i = 0; i < k; i++) ss += f[i] * f[i];
        double norm = Math.sqrt(ss) + 1e-3;
        for (int i = 0; i < k; i++) f[i] /= norm;
        for (int y = 0; y < PH; y += 2)
            for (int x = 0; x < PW; x += 2)
                f[k++] = (nn[y * PW + x] + nn[y * PW + x + 1] + nn[(y + 1) * PW + x] + nn[(y + 1) * PW + x + 1]) / 4.0 * 0.25;
        for (int y = 0; y < PH; y++) {
            double mn = Double.MAX_VALUE;
            for (int x = 0; x < PW; x++) mn = Math.min(mn, nn[y * PW + x]);
            f[k++] = mn * 0.25;
        }
        return f;
    }

    static double predict(double[] f) {
        double z = W[NH * NF + NH + NH];
        for (int j = 0; j < NH; j++) {
            double a = W[NH * NF + j];
            int o = j * NF;
            for (int i = 0; i < NF; i++) a += W[o + i] * f[i];
            if (a > 0) z += a * W[NH * NF + NH + j];
        }
        return 1.0 / (1.0 + Math.exp(-z));
    }

    private static final String MODEL =
        "" +
        "" +
        "" +
        "";
}
